<template>
  <div class="live-page"><header class="live-topbar"><div class="live-title"><span class="brand-mark">R</span><div><strong>{{ classInfo?.code || 'Live Classroom' }}</strong><span>{{ classInfo?.name || session?.mediaRoomId || 'Đang kết nối' }}</span></div></div><div class="topbar-actions"><span class="status-pill success">{{ connectionState }}</span><button class="button secondary" @click="leave">Rời lớp</button></div></header><div v-if="error" class="error-banner" style="margin:14px;background:#2b1d23;border-color:#6c2f39;color:#ffb4b4"><span>{{ error }}</span><button class="mini-button" @click="load">Thử lại</button></div><main class="live-body"><section class="media-stage"><div class="media-placeholder"><div class="media-avatar">{{ initials }}</div><strong>{{ isSessionStarted ? 'Media plane' : 'Phiên chưa bắt đầu' }}</strong><span>{{ joined?.media.serverUrl || (isSessionStarted ? 'Đang chờ quyền truy cập media' : 'Giáo viên cần bắt đầu phiên trước khi join.') }}</span><small style="color:#7f8da1">WebRTC/SFU boundary tách khỏi class state và submission.</small></div></section><aside class="live-side"><section class="live-panel"><div class="live-panel-header"><strong>Class Overview</strong><span>{{ participants.length }} kết nối</span></div><div class="live-panel-body"><div v-if="participants.length" class="list-compact"><div v-for="participant in participants" :key="participant" class="overview-row"><div class="overview-student"><i class="student-dot"></i><strong>{{ participant === auth.account?.id ? `${auth.account?.displayName} (bạn)` : participant.slice(0, 8) }}</strong></div><span class="overview-cell">Online</span><span class="overview-progress"><i style="width:100%"></i></span></div></div><div v-else class="empty-state"><strong>Chưa có participant</strong><span>Participant presence sẽ cập nhật khi người dùng kết nối.</span></div><div v-if="isTeacher && overview" style="margin-top:14px"><RouterLink class="button ghost" :to="`/activities/${overview.activityId}?sessionId=${session?.id}`">Mở activity overview</RouterLink></div><div v-if="isTeacher && raisedHands.length" class="raised-hands"><div class="panel-heading"><h3>Đang giơ tay</h3><span>{{ raisedHands.length }}</span></div><div v-for="hand in raisedHands" :key="hand.studentId" class="raised-hand-row"><strong>{{ hand.studentId.slice(0, 8) }}</strong><span>{{ formatTime(hand.raisedAt) }}</span><button class="mini-button" @click="clearHand(hand.studentId)">Đã gọi</button></div></div></div></section><section v-if="isTeacher && attendance" class="live-panel attendance-panel"><div class="live-panel-header"><strong>Điểm danh</strong><span>{{ attendance.attendancePercentage }}%</span></div><div class="attendance-metrics"><span><strong>{{ attendance.presentCount }}</strong> Có mặt</span><span><strong>{{ attendance.lateCount }}</strong> Muộn</span><span><strong>{{ attendance.absentCount }}</strong> Vắng</span><span><strong>{{ attendance.excusedCount }}</strong> Có phép</span></div><div class="live-panel-body"><div v-if="attendanceRows.length" class="list-compact"><div v-for="student in attendanceRows" :key="student.studentId" class="attendance-row"><div class="overview-student"><i class="student-dot"></i><strong>{{ student.studentId.slice(0, 8) }}</strong></div><select v-model="attendanceDrafts[student.studentId].status" class="form-select attendance-select"><option value="Present">Có mặt</option><option value="Late">Muộn</option><option value="Absent">Vắng</option><option value="Excused">Có phép</option></select><input v-model.trim="attendanceDrafts[student.studentId].reason" class="form-input attendance-reason" placeholder="Lý do" /><button class="mini-button" :disabled="attendanceBusy === student.studentId" @click="adjustAttendance(student.studentId)">{{ attendanceBusy === student.studentId ? '…' : 'Lưu' }}</button></div></div><div v-else class="empty-state"><strong>Chưa có roster</strong><span>Điểm danh sẽ xuất hiện khi lớp có học viên.</span></div></div></section><section class="live-panel live-chat"><div class="live-panel-header"><strong>Chat</strong><span>{{ messages.length }} tin nhắn</span></div><div class="chat-messages"><div v-for="message in messages" :key="message.id" class="chat-message"><strong>{{ message.senderId === auth.account?.id ? 'Bạn' : message.senderId.slice(0, 8) }}</strong><span>{{ message.body }}</span></div><div v-if="!messages.length" class="empty-state"><strong>Chưa có tin nhắn</strong><span>Trao đổi nhanh trong phiên học.</span></div></div><form class="chat-form" @submit.prevent="send"><input v-model.trim="draft" placeholder="Viết tin nhắn…" :disabled="!canChat" /><button class="button primary" :disabled="!draft || !canChat">Gửi</button></form></section></aside></main><footer class="live-footer"><button v-if="!isTeacher" class="button secondary" @click="toggleHand">{{ handRaised ? 'Hạ tay' : 'Giơ tay' }}</button><button v-if="isTeacher && !isSessionStarted" class="button primary" @click="start">Bắt đầu phiên</button><button v-if="isTeacher && isSessionStarted" class="button danger" @click="end">Kết thúc phiên</button></footer></div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'; import { HubConnectionBuilder, LogLevel, type HubConnection } from '@microsoft/signalr'; import { useRoute, useRouter } from 'vue-router'; import { useAuthStore } from '../../../shared/stores/auth'; import { academicsApi, assessmentApi, classroomApi } from '../../../shared/api/client'; import { errorMessage } from '../../../shared/api/http'; import { type AttendanceSummary, type ClassOverview, type LearningClass, type LiveJoinResponse, type LiveSession } from '../../../shared/types'
type Enrollment = { id: string; studentId: string; status: string | number; enrolledAt: string }
const route = useRoute(); const router = useRouter(); const auth = useAuthStore(); const session = ref<LiveSession | null>(null); const joined = ref<LiveJoinResponse | null>(null); const classInfo = ref<LearningClass | null>(null); const participants = ref<string[]>([]); const messages = ref<{ id: string; senderId: string; body: string; sentAt: string }[]>([]); const draft = ref(''); const handRaised = ref(false); const error = ref(''); const connection = ref<HubConnection | null>(null); const connectionState = ref('Đang kết nối'); const overview = ref<ClassOverview | null>(null); const attendance = ref<AttendanceSummary | null>(null); const enrollments = ref<Enrollment[]>([]); const attendanceDrafts = ref<Record<string, { status: string; reason: string }>>({}); const attendanceBusy = ref(''); const isTeacher = computed(() => auth.role === 'teacher' || auth.role === 'admin'); const isSessionStarted = computed(() => { const status = session.value?.status; return status === 1 || String(status).toLowerCase() === 'started' }); const canChat = computed(() => Boolean(joined.value)); const attendanceRows = computed(() => enrollments.value.map(item => ({ studentId: item.studentId }))); const initials = computed(() => (auth.account?.displayName || 'RL').split(/\s+/).slice(-2).map(item => item[0]).join('').toUpperCase())
const raisedHands = ref<{ id: string; liveSessionId: string; studentId: string; status: string | number; raisedAt: string; loweredAt?: string; clearedBy?: string }[]>([])
function formatTime(value: string) { return new Date(value).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) }
function attendanceStatus(status: string | number | undefined) { return status === 1 || String(status).toLowerCase() === 'late' ? 'Late' : status === 2 || String(status).toLowerCase() === 'absent' ? 'Absent' : status === 3 || String(status).toLowerCase() === 'excused' ? 'Excused' : 'Present' }
function syncAttendanceDrafts() { const records = attendance.value?.records || []; attendanceDrafts.value = Object.fromEntries(enrollments.value.map(item => { const record = records.find(value => value.studentId === item.studentId); return [item.studentId, { status: attendanceStatus(record?.status), reason: record?.adjustmentReason || '' }] })) }
async function adjustAttendance(studentId: string) { if (!session.value) return; const draftValue = attendanceDrafts.value[studentId]; if (!draftValue?.reason.trim()) { error.value = 'Điều chỉnh điểm danh cần có lý do.'; return } attendanceBusy.value = studentId; try { await classroomApi.adjustAttendance(session.value.id, studentId, { status: draftValue.status, reason: draftValue.reason.trim() }); attendance.value = await classroomApi.attendance(session.value.id); syncAttendanceDrafts() } catch (cause) { error.value = errorMessage(cause) || 'Không điều chỉnh được điểm danh.' } finally { attendanceBusy.value = '' } }
async function load() { error.value = ''; joined.value = null; try { classInfo.value = (await academicsApi.classDetail(String(route.params.classId))).class; session.value = await classroomApi.session(String(route.params.sessionId)); if (!isSessionStarted.value) { connectionState.value = 'Chưa bắt đầu'; return } joined.value = await classroomApi.joinSession(session.value.id); messages.value = await classroomApi.messages(session.value.id); if (isTeacher.value) { const [attendanceResult, enrollmentResult, handsResult] = await Promise.allSettled([classroomApi.attendance(session.value.id), academicsApi.enrollments(session.value.learningClassId), classroomApi.raiseHands(session.value.id)]); if (attendanceResult.status === 'fulfilled') attendance.value = attendanceResult.value; if (enrollmentResult.status === 'fulfilled') enrollments.value = enrollmentResult.value; if (handsResult.status === 'fulfilled') raisedHands.value = handsResult.value; syncAttendanceDrafts() } await connect(); if (isTeacher.value && typeof route.query.activityId === 'string') overview.value = await assessmentApi.overview(session.value.learningClassId, route.query.activityId) } catch (cause) { error.value = errorMessage(cause) || 'Không thể tham gia live classroom.'; connectionState.value = 'Không kết nối' } }
async function start() { if (!session.value) return; try { session.value = await classroomApi.startSession(session.value.id); await load() } catch (cause) { error.value = errorMessage(cause) || 'Không bắt đầu được phiên.' } }; async function end() { if (!session.value) return; try { session.value = await classroomApi.endSession(session.value.id); await connection.value?.stop(); connectionState.value = 'Đã kết thúc' } catch (cause) { error.value = errorMessage(cause) || 'Không kết thúc được phiên.' } }
async function clearHand(studentId: string) { if (!session.value) return; try { await classroomApi.clearHand(session.value.id, studentId); raisedHands.value = raisedHands.value.filter(hand => hand.studentId !== studentId) } catch (cause) { error.value = errorMessage(cause) || 'Không xử lý được yêu cầu giơ tay.' } }
async function connect() { if (!session.value) return; await connection.value?.stop().catch(() => undefined); const hub = new HubConnectionBuilder().withUrl(`/hubs/live/${session.value.id}`).withAutomaticReconnect().configureLogging(LogLevel.Warning).build(); hub.on('participant-joined', (delta: { userId: string }) => { if (!participants.value.includes(delta.userId)) participants.value.push(delta.userId) }); hub.on('participant-left', (delta: { userId: string }) => { participants.value = participants.value.filter(id => id !== delta.userId) }); hub.on('hand-raised', (hand: { studentId: string; id: string; liveSessionId: string; status: string | number; raisedAt: string }) => { if (!isTeacher.value || raisedHands.value.some(item => item.id === hand.id)) return; raisedHands.value.push(hand) }); hub.on('hand-lowered', (hand: { studentId: string }) => { raisedHands.value = raisedHands.value.filter(item => item.studentId !== hand.studentId) }); hub.on('chat-message', (message: { id: string; senderId: string; body: string; sentAt: string }) => { if (!messages.value.some(item => item.id === message.id)) messages.value.push(message) }); hub.onreconnecting(() => { connectionState.value = 'Đang kết nối lại' }); hub.onreconnected(() => { connectionState.value = 'Đã kết nối'; hub.invoke('RefreshPresence').catch(() => undefined) }); hub.onclose(() => { connectionState.value = 'Đã ngắt kết nối' }); try { await hub.start(); connection.value = hub; connectionState.value = 'Đã kết nối'; if (auth.account?.id && !participants.value.includes(auth.account.id)) participants.value.push(auth.account.id) } catch (cause) { error.value = errorMessage(cause) || 'Không kết nối được realtime.' } }
async function send() { if (!session.value || !draft.value) return; const body = draft.value; draft.value = ''; try { const message = await classroomApi.sendMessage(session.value.id, body) as { id: string; senderId: string; body: string; sentAt: string }; if (!messages.value.some(item => item.id === message.id)) messages.value.push(message) } catch (cause) { error.value = errorMessage(cause) || 'Không gửi được tin nhắn.' } }; async function toggleHand() { if (!session.value) return; try { if (handRaised.value) { await classroomApi.lowerHand(session.value.id); handRaised.value = false } else { await classroomApi.raiseHand(session.value.id); handRaised.value = true } } catch (cause) { error.value = errorMessage(cause) || 'Không cập nhật được trạng thái giơ tay.' } }; async function leave() { if (joined.value && session.value) await classroomApi.leaveSession(session.value.id).catch(() => undefined); await connection.value?.stop().catch(() => undefined); await router.push(`/classes/${route.params.classId}`) }
onMounted(load); onBeforeUnmount(async () => { if (joined.value && session.value) await classroomApi.leaveSession(session.value.id).catch(() => undefined); await connection.value?.stop().catch(() => undefined) })
</script>
